import React, { useState, useEffect } from "react";
import Modal from "react-modal";
import "./Library.css";

Modal.setAppElement("#root");

const Library = () => {
  const [videos, setVideos] = useState([]);
  const [selectedVideo, setSelectedVideo] = useState(null);

  useEffect(() => {
    const fetchVideos = async () => {
      const userId = localStorage.getItem("user_id");
      if (!userId) return;

      try {
        const response = await fetch(`http://34.55.142.231:5000/videos/${userId}`);
        const data = await response.json();
        setVideos(data);
      } catch (error) {
        console.error("Error fetching videos:", error);
      }
    };

    fetchVideos();
  }, []);

  const handleOpenModal = (video) => {
    setSelectedVideo(video);
  };

  const handleCloseModal = () => {
    setSelectedVideo(null);
  };

  return (
    <div className="resource-section">
      <h1>Library</h1>
      <div className="resource-content">
        <div className="video-container">
          {videos.map((video) => (
            <div key={video.video_id} className="video-card">
              <div className="video-card-content">
                <img src="https://via.placeholder.com/150" alt="Video Thumbnail" className="video-thumbnail" />
                <h3>{video.video_filename}</h3>
                <p>Click Read More to view AI Feedback</p>
                <button className="read-more-btn" onClick={() => handleOpenModal(video)}>Read More</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {selectedVideo && (
        <Modal
          isOpen={true}
          onRequestClose={handleCloseModal}
          contentLabel="Video Details"
          className="modal"
          overlayClassName="modal-overlay"
        >
          <h2>Video Replay</h2>
          <video width="100%" height="auto" controls>
            <source src={`http://34.55.142.231:5000/uploads/${selectedVideo.video_filename}`} type="video/mp4" />
            Your browser does not support the video tag.
          </video>
          <h2 style={{ marginTop: "20px" }}>AI Feedback</h2>
          <pre style={{ whiteSpace: "pre-wrap", textAlign: "left" }}>{selectedVideo.feedback}</pre>

          <button onClick={handleCloseModal} style={{ marginTop: "20px" }}>
            Close
          </button>
        </Modal>
      )}
    </div>
  );
};

export default Library;
